/// MMIO Region
///
/// MMIO region excludes any memory that is separate from the module
/// configuration space, i.e. ROM, main SRAM, and mbx SRAM are excluded but
/// retention SRAM or spi_device are included.
pub const TOP_MIO_MMIO_BASE_ADDR: usize = 0x211C0000;
pub const TOP_MIO_MMIO_SIZE_BYTES: usize = 0xF441000;
